package com.example.complaintmanagement.mapper; import com.example.complaintmanagement.entity.User; import com.example.complaintmanagement.dto.UserDtos.UserResponse; public class UserMapper { public UserResponse toResponse(User u){ return new UserResponse(u.getId(),u.getFirstName(),u.getLastName(),u.getUsername(),u.getEmail(),u.getRole(),u.isActive(),u.getCreatedAt()==null?null:u.getCreatedAt().toString()); } }